<?php
declare(strict_types=1);
header('X-Content-Type-Options: nosniff');
function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function fmtdate($v):string{return $v?gmdate('M j, Y H:i', (int)$v).' UTC':'Unknown';}
function num($v):string{return number_format((float)($v??0));}
$names=['1'=>'PC','32'=>'PlayStation','64'=>'Xbox'];
$mapNames=['MP_Abandoned'=>'Zavod 311','MP_Damage'=>'Lancang Dam','MP_Flooded'=>'Flood Zone','MP_Journey'=>'Golmud Railway','MP_Naval'=>'Paracel Storm','MP_Prison'=>'Operation Locker','MP_Resort'=>'Hainan Resort','MP_Siege'=>'Siege of Shanghai','MP_TheDish'=>'Rogue Transmission','MP_Tremors'=>'Dawnbreaker','XP1_001'=>'Silk Road','XP1_002'=>'Altai Range','XP1_003'=>'Guilin Peaks','XP1_004'=>'Dragon Pass','XP0_Caspian'=>'Caspian Border 2014','XP0_Firestorm'=>'Firestorm 2014','XP0_Metro'=>'Operation Metro 2014','XP0_Oman'=>'Gulf of Oman 2014','XP2_001'=>'Lost Islands','XP2_002'=>'Nansha Strike','XP2_003'=>'Wave Breaker','XP2_004'=>'Operation Mortar','XP3_MarketPl'=>'Pearl Market','XP3_Prpganda'=>'Propaganda','XP3_UrbanGdn'=>'Lumphini Garden','XP3_WtrFront'=>'Sunken Dragon','XP4_Arctic'=>'Operation Whiteout','XP4_SubBase'=>'Hammerhead','XP4_Titan'=>'Hangar 21','XP4_WlkrFtry'=>'Giants of Karelia','XP5_Night_01'=>'Zavod:Graveyard Shift','XP6_CMP'=>'Operation Outbreak','XP7_Valley'=>'Dragon Valley 2015'];
function mapLabel($code):string{global $mapNames;return $mapNames[(string)$code]??(string)($code??'Unknown');}
function modeLabel($code):string{return ['2'=>'Rush','64'=>'Conquest Large','1024'=>'Domination','2097152'=>'Obliteration','8388608'=>'Air Superiority'][(string)$code]??(string)($code??'Unknown');}
function serverTone($name):int{return (int)(hexdec(substr(hash('sha256',strtolower((string)$name)),0,4))%6);}
$db=pg_connect('dbname=bf4_battle_reports user=www-data');
if(!$db){http_response_code(503);exit('Database unavailable');}
$p=(string)($_GET['platform']??'all');if($p!=='all'&&!isset($names[$p]))$p='all';
$id=(string)($_GET['report']??'');if(!preg_match('/^[0-9]{1,19}$/',$id))$id='';
$person=(string)($_GET['persona']??'');if(!preg_match('/^[0-9]{1,19}$/',$person))$person='';
$playerSearch=trim((string)($_GET['player']??''));$playerSearch=substr($playerSearch,0,120);
$serverSearch=trim((string)($_GET['server']??''));$serverSearch=substr($serverSearch,0,120);
$mapFilter=(string)($_GET['map']??'all');if($mapFilter!=='all'&&!isset($mapNames[$mapFilter]))$mapFilter='all';
$modeNames=['2'=>'Rush','64'=>'Conquest Large','1024'=>'Domination','2097152'=>'Obliteration','8388608'=>'Air Superiority'];
$modeFilter=(string)($_GET['mode']??'all');if($modeFilter!=='all'&&!isset($modeNames[$modeFilter]))$modeFilter='all';
asort($mapNames,SORT_NATURAL|SORT_FLAG_CASE);asort($modeNames,SORT_NATURAL|SORT_FLAG_CASE);
$page=max(1,min(100,(int)($_GET['page']??1)));
$filter=$p==='all'?'':' AND r.platform=$1';
$report=null;$players=[];$teams=[];$list=[];$stats=[];$totalReports=0;$totalPages=1;$matchedPlayer=null;
if($person!==''){$found=pg_query_params($db,'SELECT platform,persona_id,current_name FROM players WHERE persona_id=$1'.($p==='all'?'':' AND platform=$2').' ORDER BY latest_report_at DESC LIMIT 1',$p==='all'?[$person]:[$person,$p]);$matchedPlayer=$found?(pg_fetch_assoc($found)?:null):null;}
if($id!==''){
 $res=pg_query_params($db,"SELECT r.platform,r.battlelog_report_id,d.report_json::text AS payload FROM battle_reports r JOIN battle_report_details d ON d.platform=r.platform AND d.battlelog_report_id=r.battlelog_report_id WHERE r.battlelog_report_id=$1".($p==='all'?'':' AND r.platform=$2')." LIMIT 1",$p==='all'?[$id]:[$id,$p]);
 $report=pg_fetch_assoc($res)?:null;
 if($report){
  $payload=json_decode($report['payload'],true)?:[];
  $teams=array_values($payload['teams']??[]);
  $players=array_values($payload['players']??[]);
  usort($players,fn($a,$b)=>(int)($b['combatScore']??0)<=>(int)($a['combatScore']??0));
 }
}else{
 $stats=pg_fetch_all(pg_query($db,"SELECT p.platform, (SELECT count(*) FROM battle_report_raw x WHERE x.platform=p.platform) archived,(SELECT count(*) FROM history_discoveries x WHERE x.platform=p.platform) discovered,(SELECT count(*) FROM battle_report_fetch_log x WHERE x.platform=p.platform AND x.outcome <> 'ok') failed_attempts FROM (VALUES (1),(32),(64)) p(platform)"))?:[];
 $params=[];$where=' WHERE 1=1';
 if($p!=='all'){$params[]=$p;$where.=' AND r.platform=$'.count($params);}
 if($person!==''){$params[]=$person;$where.=' AND EXISTS(SELECT 1 FROM report_players rp JOIN players pl ON pl.id=rp.player_id WHERE rp.report_id=r.id AND pl.persona_id=$'.count($params).')';}
 if($playerSearch!==''){$params[]=$playerSearch;$where.=' AND r.id IN (SELECT rp.report_id FROM report_players rp JOIN players pl ON pl.id=rp.player_id WHERE (strpos(lower(pl.current_name),lower($'.count($params).'))>0 OR strpos(lower(rp.player_name_observed),lower($'.count($params).'))>0))';}
 if($serverSearch!==''){$params[]=$serverSearch;$where.=' AND strpos(lower(s.current_name),lower($'.count($params).')) > 0';}
 if($mapFilter!=='all'){$params[]=$mapFilter;$where.=" AND d.report_json->'gameServer'->>'map'=$".count($params);}
 if($modeFilter!=='all'){$params[]=$modeFilter;$where.=" AND d.report_json->>'gameMode'=$".count($params);}
 $countSql='SELECT count(*) FROM battle_reports r JOIN servers s ON s.id=r.server_id JOIN battle_report_details d ON d.platform=r.platform AND d.battlelog_report_id=r.battlelog_report_id'.$where;
 $countRes=pg_query_params($db,$countSql,$params);
 $totalReports=$countRes?(int)pg_fetch_result($countRes,0,0):0;
 $totalPages=max(1,(int)ceil($totalReports/30));$page=min($page,$totalPages);
 $params[]=30;$lim='$'.count($params);$params[]=($page-1)*30;$off='$'.count($params);
 $sql="SELECT r.platform,r.battlelog_report_id,r.report_timestamp,s.current_name,s.server_guid,(SELECT count(*) FROM report_players rp WHERE rp.report_id=r.id) player_count,d.report_json->'gameServer'->>'map' map_code,d.report_json->>'gameMode' mode,d.report_json->>'duration' duration FROM battle_reports r JOIN servers s ON s.id=r.server_id JOIN battle_report_details d ON d.platform=r.platform AND d.battlelog_report_id=r.battlelog_report_id".$where." ORDER BY r.report_timestamp DESC LIMIT $lim OFFSET $off";
 $res=pg_query_params($db,$sql,$params);$list=$res?pg_fetch_all($res)?:[]:[];
}
function playerExternalLinks(array $pl):array{
 $pid=rawurlencode((string)$pl['persona_id']);$name=rawurlencode((string)$pl['current_name']);$platform=(string)$pl['platform'];
 $slug=['1'=>'pc','32'=>'ps4','64'=>'xboxone'][$platform]??'pc';
 $links=['BF4 Player Stats'=>'https://bf4playerstats.com/search?query='.$name,'Battlelog'=>'https://battlelog.battlefield.com/bf4/soldier/'.$name.'/stats/'.$pid.'/'.$slug.'/'];
 if($platform==='1'){$links['BF4DB']='https://bf4db.com/player/'.$pid;$links['Battlefield Agency']='https://battlefield.agency/search?q='.$pid;$links['BF4 Cheat Report']='https://bf4cheatreport.com/?pid='.$pid.'&cnt=200';}
 return $links;
}
function urlq(array $changes):string{return '?'.http_build_query(array_merge($_GET,$changes));}
function battlelogServerUrl($platform,$guid):?string{
 $slug=['1'=>'pc','32'=>'ps4','64'=>'xboxone'][(string)$platform]??null;
 if(!$slug||!is_string($guid)||!preg_match('/^[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}$/',$guid))return null;
 return 'https://battlelog.battlefield.com/bf4/servers/show/'.$slug.'/'.$guid.'/';
}
